pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero-attempt configuration is invalid according to the config contract;
    // treating it as one attempt keeps the runner from silently skipping work.
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;
    let mut delay_ms = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(delay_ms);
                delay_ms = delay_ms
                    .saturating_mul(2)
                    .min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }
}

