use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn exported_runner_retries_transient_failures_with_a_bounded_schedule() {
    let config = RetryConfig {
        max_attempts: 6,
        base_delay_ms: 7,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 6 {
            Err(RetryError::Transient("service unavailable".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 6);
    assert_eq!(sleeper.sleeps, vec![7, 14, 20, 20, 20]);
}

#[test]
fn exported_runner_stops_at_the_attempt_limit_and_preserves_the_error() {
    let config = RetryConfig {
        max_attempts: 2,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient(format!("attempt {calls}")))
    });

    assert_eq!(result, Err(RetryError::Transient("attempt 2".into())));
    assert_eq!(calls, 2);
    assert_eq!(sleeper.sleeps, vec![10]);
}

